INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43511, 'Psalms 22:11', 'Psalms', 22, 11, 'لېرې کېږه مه له ما نه دی کړاو رانژدې شوی هېڅوک نشته دی د مرستې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_11.mp3', '', 1761754199, 1761754199),
(43512, 'Psalms 22:12', 'Psalms', 22, 12, 'ډېر دښمنان رانه چاپېر دي د غویانو په څېر دي په مثال د غویانو زورورو د باشان د سیمې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_12.mp3', '', 1761754199, 1761754199),
(43513, 'Psalms 22:13', 'Psalms', 22, 13, 'زما دښمنان لکه زمریان دي خولې یې خلاصې غړمبار کړي هم کوي په ما بریدونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_13.mp3', '', 1761754199, 1761754199),
(43514, 'Psalms 22:14', 'Psalms', 22, 14, 'لکه توی چې شي اوبه په ځمکه باندې داسې لاړلو قوت مې له بدنه ټول هډوکي مې بندونو نه جدا شول زړه زما شولو د موم په شان اوبه زما سینه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_14.mp3', '', 1761754199, 1761754199),
(43515, 'Psalms 22:15', 'Psalms', 22, 15, 'زور مې ټول لکه د خټو د کودي په شانتې خلاص شو په تالو پورې مې ژبه ده نښتې زه دې پرېښودمه مرګ ته په ګردونو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_15.mp3', '', 1761754199, 1761754199),
(43516, 'Psalms 22:16', 'Psalms', 22, 16, 'بدکاران خلک زما نه راچاپېر شول لکه د سپیانو په شان راتاو شول رانه پښې او لاسونه یې زما وداړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_16.mp3', '', 1761754199, 1761754199),
(43517, 'Psalms 22:17', 'Psalms', 22, 17, 'شم شمېرلی مې هډوکي د بدن ټول دښمنان زما په ځیر ځیر راته ګوري او خوشحالیږي په ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_17.mp3', '', 1761754199, 1761754199),
(43518, 'Psalms 22:18', 'Psalms', 22, 18, 'اچوي پچه دوی زما په جامو او یې وېشي په خپل منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_18.mp3', '', 1761754199, 1761754199),
(43519, 'Psalms 22:19', 'Psalms', 22, 19, 'خو ای څښتنه، لېرې کېږه مه له ما نه ای زما ځواکه، بیړه کوه زما مرستې ته راشه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_19.mp3', '', 1761754199, 1761754199),
(43520, 'Psalms 22:20', 'Psalms', 22, 20, 'زما ځان خلاص کړه د تورې د ګوزار نه قیمتي ژوند زما وژغوره له سپیانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_20.mp3', '', 1761754199, 1761754199),
(43521, 'Psalms 22:21', 'Psalms', 22, 21, 'د زمرو د خولې مې خلاص کړه هم مې خلاص کړه د وحشي غویو د ښکرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_21.mp3', '', 1761754199, 1761754199),
(43522, 'Psalms 22:22', 'Psalms', 22, 22, 'زه به اعلان کړمه ستا نوم خپلو خلکو ته د دوی غونډه کې به وکړم ستا ثنا او صفت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_22.mp3', '', 1761754199, 1761754199),
(43523, 'Psalms 22:23', 'Psalms', 22, 23, 'له څښتنه چې وېرېږئ، د هغه ثنا ووایئ! ای د یعقوب اولادې، ټول کړئ عزت د هغه! د اسراییلو ټولو خلکو، کړئ عبادت د هغه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_23.mp3', '', 1761754199, 1761754199),
(43524, 'Psalms 22:24', 'Psalms', 22, 24, 'نه دی غافل شوی غریبانو نه او نه یې د نظره غورځولی د هغوی تکلیف نه دی اړولی هغه خپل مخ له هغوی څخه هم اورېدلي فریادونه د هغوی یې د کومک دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_24.mp3', '', 1761754199, 1761754199),
(43525, 'Psalms 22:25', 'Psalms', 22, 25, 'لویه غونډه کې به وکړمه صفت ستا د کارونو په حضور د هغو خلکو چې کوي عبادت ستا زه به ورکړمه نذرونه چې یې وعده کړې ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_25.mp3', '', 1761754199, 1761754199),
(43526, 'Psalms 22:26', 'Psalms', 22, 26, 'غریبان چې څومره غواړي دوی به وخوري چې رجوع کوي څښتن ته د هغه ثنا به وایي تل ترتله دې نېکمرغه وي هغوی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_26.mp3', '', 1761754199, 1761754199),
(43527, 'Psalms 22:27', 'Psalms', 22, 27, 'ټوله ځمکه به څښتن یادوي هم به ټول ده ته راواوړي ټول قومونه به څښتن ته په سجده شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_27.mp3', '', 1761754199, 1761754199),
(43528, 'Psalms 22:28', 'Psalms', 22, 28, 'ځکه دی څښتن پاچا حکومت کړي په قومونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_28.mp3', '', 1761754199, 1761754199),
(43529, 'Psalms 22:29', 'Psalms', 22, 29, 'ټول مغرور خلک به ده ته سجده کاندي ټول فاني خلک به ده ته په سجده شي او هغوی چې ځان ژوندي ساتلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_29.mp3', '', 1761754199, 1761754199),
(43530, 'Psalms 22:30', 'Psalms', 22, 30, 'عبادت به د هغه کوي راتلونکي نسلونه د څښتن په باب به وکاندي بل نسل ته بیان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_30.mp3', '', 1761754199, 1761754199),
(43531, 'Psalms 22:31', 'Psalms', 22, 31, 'دا به وویل شي هغو ته چې لا نه دي پیدا شوي: «څښتن ژغورلي یو مونږ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_31.mp3', '', 1761754199, 1761754199),
(43532, 'Jeremiah 1:1', 'Jeremiah', 1, 1, 'په دې کِتاب کښې د خِلقياه د زوئ يرمياه پېغامونه دى ‎څوک چې د بنيامين په علاقه کښې د عنتوت په ښار کښې د اِمامانو نه يو اِمام وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_1.mp3', '', 1761754199, 1761754199),
(43533, 'Jeremiah 1:2', 'Jeremiah', 1, 2, 'د مالِک خُدائ کلام په اول ځل په يرمياه د امون په زوئ يوسياه د يهوداه د بادشاهت په ديارلسم کال نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_2.mp3', '', 1761754199, 1761754199),
(43534, 'Jeremiah 1:3', 'Jeremiah', 1, 3, 'او يرمياه ته دا پېغامونه تر دې چې د يهويقيم د يوسياه د زوئ د يهوداه بادشاه په ټول حکومت کښې او د يهوداه بادشاه د يوسياه د زوئ د صدقياه د حکومت د يوولسم کال تر پينځمې مياشتې پورې مِلاوېدل کله چې د يروشلم خلق جلاوطن کړے شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_3.mp3', '', 1761754199, 1761754199),
(43535, 'Jeremiah 1:4', 'Jeremiah', 1, 4, 'د مالِک خُدائ کلام په ما نازل شو او ما ته يې وفرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_4.mp3', '', 1761754199, 1761754199),
(43536, 'Jeremiah 1:5', 'Jeremiah', 1, 5, '”ما تۀ د هغه وخت نه پېژندلې چې لا د مور په خېټه شوے نۀ وې، ستا د پېدا کېدو نه وړاندې مې تۀ غوره کړې او د قومونو دپاره مې نبى مقرر کړې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_5.mp3', '', 1761754199, 1761754199),
(43537, 'Jeremiah 1:6', 'Jeremiah', 1, 6, 'خو ما ورته ووئيل چې، ”اے قادر مطلق خُدايه، ما ته خو د صحيح خبرو کولو طريقه هم نۀ راځى ځکه چې زۀ خو لا هلک يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_6.mp3', '', 1761754199, 1761754199),
(43538, 'Jeremiah 1:7', 'Jeremiah', 1, 7, 'خو مالِک خُدائ ما ته وفرمائيل چې، ”داسې مۀ وايه چې زۀ لا هلک يم ځکه زۀ چې هر چا ته تا ورلېږم نو تۀ به ورځې او هر څۀ چې درته وايم هغه به ورته وائې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_7.mp3', '', 1761754199, 1761754199),
(43539, 'Jeremiah 1:8', 'Jeremiah', 1, 8, 'د خلقو نه مۀ يرېږه، ځکه چې زۀ مالِک خُدائ دا وايم چې زۀ ستا مل يم، او زۀ به تا بچ ساتم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_8.mp3', '', 1761754199, 1761754199),
(43540, 'Jeremiah 1:9', 'Jeremiah', 1, 9, 'نو بيا مالِک خُدائ خپل لاس راوږد کړو، او زما خولې له يې راوړو او راته يې وفرمائيل، ”ګوره، ما خپل کلام ستا په خولۀ کښې واچولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_9.mp3', '', 1761754199, 1761754199),
(43541, 'Jeremiah 1:10', 'Jeremiah', 1, 10, 'نن ما تۀ په قومونو او بادشاهتونو باندې مقرر کړې، او تا ته مې په هغوئ د بېخ نه د راويستلو، او د هغوئ د رانسکورولو، بربادولو او د اخوا غورزولو، او په هغې د نورو د قائمولو او د کَرلو اختيار درکړو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_10.mp3', '', 1761754199, 1761754199),
(43542, 'Jeremiah 1:11', 'Jeremiah', 1, 11, 'نو بيا د مالِک خُدائ کلام په ما نازل شو او وې فرمائيل، ”يرمياه، تا ته څۀ ښکارى؟“ ما ورته ووئيل، ”ما ته د بادام د ونې يوه څانګه ښکارى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_11.mp3', '', 1761754199, 1761754199),
(43543, 'Jeremiah 1:12', 'Jeremiah', 1, 12, 'مالِک خُدائ راته وفرمائيل، ”تا ته ټيک ښکارى، د دې دا مطلب دے چې ‎‎‎‎‎‎زۀ د خپل کلام ساتونکے يم، زۀ چې څۀ وايم چې هغه پوره شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_12.mp3', '', 1761754199, 1761754199),
(43544, 'Jeremiah 1:13', 'Jeremiah', 1, 13, 'د مالِک خُدائ کلام دوباره په ما نازل شو او وې فرمائيل، ”نور څۀ وينې؟“ ما ورته ووئيل، ”زۀ د شمال طرف نه دېګ وينم چې څۀ په کښې يشيږى او د دېګ خولۀ زمونږ په طرف راټيټه ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_13.mp3', '', 1761754199, 1761754199),
(43545, 'Jeremiah 1:14', 'Jeremiah', 1, 14, 'نو مالِک خُدائ ما ته بيا وفرمائيل چې، ”دغه شان به په دې مُلک او څوک چې په کښې اوسيږى په هغوئ به د شمال نه د جنوب طرف ته افت راښکته شى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_14.mp3', '', 1761754199, 1761754199),
(43546, 'Jeremiah 1:15', 'Jeremiah', 1, 15, 'نو وګورئ، زۀ قومونه د شمال د بادشاهتونو نه راغونډوم. د دُنيا بادشاهان به يروشلم او د يهوداه په ټولو ښارونو حمله وکړى او هغوئ به خپل تختونه د يروشلم د ښار په دروازه کښې قائم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_15.mp3', '', 1761754199, 1761754199),
(43547, 'Jeremiah 1:16', 'Jeremiah', 1, 16, 'نو زۀ به خپله سزا په خپل غوره شوى قوم نازله کړم او د هغوئ د شرارت په وجه به هغوئ ته سزا ورکړم ځکه چې دوئ زۀ رد کړم او غېرو خُدايانو ته يې خوشبويانې وسوزولې او د خپلو لاسونو جوړو شوو بُتانو ته يې عبادت وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_16.mp3', '', 1761754199, 1761754199),
(43548, 'Jeremiah 1:17', 'Jeremiah', 1, 17, 'نو تۀ يرمياه اوس ځان تيار کړه، او راپاڅه او هر هغه څۀ چې زۀ درته وايم دا هغوئ ته ووايه. د هغوئ نه مۀ يرېږه، ګنې زۀ به تا د هغوئ په وړاندې سخت ويروم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_17.mp3', '', 1761754199, 1761754199),
(43549, 'Jeremiah 1:18', 'Jeremiah', 1, 18, 'ګوره، ما نن تۀ لکه د يو قلعه بند ښار په شان او د اوسپنې ستن، او د پيتلو د دېوال په شان مضبوط جوړ کړې چې تۀ د ټول مُلک سره مقابله وکړې، کۀ هغه د يهوداه بادشاهان، آفسران، اِمامان او يا د هغې ټول عوام وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_18.mp3', '', 1761754199, 1761754199),
(43550, 'Jeremiah 1:19', 'Jeremiah', 1, 19, 'هغوئ به ستا خلاف وجنګيږى خو کامياب به نۀ شى، ځکه چې زۀ ستا مل يم او زۀ به تا بچ کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah1_verse_19.mp3', '', 1761754199, 1761754199),
(43551, 'Psalms 15:1', 'Psalms', 15, 1, 'ای څښتنه څوک کولای شي چې پاتې شي ستا کور کې؟ اوسېدی شي څوک د ستا په سپېڅلي غره؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms15_verse_1.mp3', '', 1761754199, 1761754199),
(43552, 'Psalms 15:2', 'Psalms', 15, 2, 'څوک چې کاندي اطاعت د خدای هر کار کې او همېش کړي نېک کارونه چې خبرې یې رښتیا د زړه له کومي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms15_verse_2.mp3', '', 1761754199, 1761754199),
(43553, 'Psalms 15:3', 'Psalms', 15, 3, 'څوک چې نه وایي تهمت په نورو باندې څوک چې ملګرو سره بد نه کوي نه کړي خبرې ګاونډیانو پسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms15_verse_3.mp3', '', 1761754199, 1761754199),
(43554, 'Psalms 15:4', 'Psalms', 15, 4, 'څوک چې بدکارو ته په سپکه ګوري خو عزت کوي د هغو چې کړي وېره له څښتنه څوک چې وفا کوي خپلو وعدو باندې نه کړي پروا که په ضرر یې هم وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms15_verse_4.mp3', '', 1761754199, 1761754199),
(43555, 'Psalms 15:5', 'Psalms', 15, 5, 'ورکوي قرضونه نورو ته بې‌سوده نه اخلي رشوت د شاهدۍ په بې‌ګناهو کړي چې دا کارونه همېشه به مستحکم وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms15_verse_5.mp3', '', 1761754199, 1761754199),
(43556, 'Proverbs 21:1', 'Proverbs', 21, 1, 'د پاچا زړه د اوبو د ویالې په څېر د څښتن په لاس کې دی کوم طرف ته چې یې خوښه وي هلته یې بیایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_1.mp3', '', 1761754199, 1761754199),
(43557, 'Proverbs 21:2', 'Proverbs', 21, 2, 'د انسان په نظر خپلې ټولې لارې سمې ښکاري خو څښتن د زړونو په رازونو قضاوت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_2.mp3', '', 1761754199, 1761754199),
(43558, 'Proverbs 21:3', 'Proverbs', 21, 3, 'څښتن د قربانۍ نه عدالت او انصاف کول ډېر خوښوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_3.mp3', '', 1761754199, 1761754199),
(43559, 'Proverbs 21:4', 'Proverbs', 21, 4, 'د بدکارانو کبرجنې سترګې او مغروره زړونه د خوارې ځمکې د حاصل په شان دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_4.mp3', '', 1761754199, 1761754199),
(43560, 'Proverbs 21:5', 'Proverbs', 21, 5, 'د خواري‌کښ انسان نقشې د ابادۍ سبب ګرځي خو ډېره بې‌صبري انسان ته نېستي راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_5.mp3', '', 1761754199, 1761754199),
(43561, 'Proverbs 21:6', 'Proverbs', 21, 6, 'په دروغجنه ژبه شتمني ګټل داسې دي لکه د مرګ په اخرنۍ سلګۍ پسې ګرځېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_6.mp3', '', 1761754199, 1761754199),
(43562, 'Proverbs 21:7', 'Proverbs', 21, 7, 'د بدکارانو ظلم به هغوی د تباهۍ په لور راکاږي ځکه چې هغوی له هر ښه کار نه انکار کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_7.mp3', '', 1761754199, 1761754199),
(43563, 'Proverbs 21:8', 'Proverbs', 21, 8, 'د ګناهکار انسان لار کږه وږه وي خو د پاک سړي کارونه رښتیني وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_8.mp3', '', 1761754199, 1761754199),
(43564, 'Proverbs 21:9', 'Proverbs', 21, 9, 'د کوټې د سر دپاسه په یو کنج کې اوسېدل د جګړه‌مارې ښځې سره په کور کې د اوسېدلو نه ښه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_9.mp3', '', 1761754199, 1761754199),
(43565, 'Proverbs 21:10', 'Proverbs', 21, 10, 'بدکاره انسان د بدۍ وږی وي او په بل چا هېڅ رحم نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_10.mp3', '', 1761754199, 1761754199),
(43566, 'Proverbs 21:11', 'Proverbs', 21, 11, 'کله چې ملنډې وهونکي ته سزا ورکول کیږي نو ساده سړی ترې حکمت حاصلوي او کله چې هوښیار ته لارښوونه وشي نو نور علم تر‌لاسه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_11.mp3', '', 1761754199, 1761754199),
(43567, 'Proverbs 21:12', 'Proverbs', 21, 12, 'عادل خدای د بدکاره کورنۍ د نژدې څخه ویني او په بدکارانو باندې بلا او تباهي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_12.mp3', '', 1761754199, 1761754199),
(43568, 'Proverbs 21:13', 'Proverbs', 21, 13, 'څوک چې د غریبانو فریاد ته خپل غوږونه بند کړي نو د هغه خپل فریاد به هېڅوک هم وانه وري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_13.mp3', '', 1761754199, 1761754199),
(43569, 'Proverbs 21:14', 'Proverbs', 21, 14, 'په پرده کې سوغات ورکول د غوسې اور سړوي او په پټه رشوت ورکول سړی د سخت غضب نه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_14.mp3', '', 1761754199, 1761754199),
(43570, 'Proverbs 21:15', 'Proverbs', 21, 15, 'عادل په انصاف کولو خوشحالیږي خو شر اچوونکي ترې وېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_15.mp3', '', 1761754199, 1761754199),
(43571, 'Proverbs 21:16', 'Proverbs', 21, 16, 'څوک چې د هوښیارۍ د لارې نه بې‌لارې شي نو هغه به د مړو په ډله کې وشمېرل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_16.mp3', '', 1761754199, 1761754199),
(43572, 'Proverbs 21:17', 'Proverbs', 21, 17, 'څوک چې عیش او عشرت خوښوي نېستمن به شي څوک چې شراب او کباب خوښوي نو شتمن به نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_17.mp3', '', 1761754199, 1761754199),
(43573, 'Proverbs 21:18', 'Proverbs', 21, 18, 'د نېکانو په ځای به بدکاران قرباني شي او خاینان به د صادقانو په ځای سزا ومومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_18.mp3', '', 1761754199, 1761754199),
(43574, 'Proverbs 21:19', 'Proverbs', 21, 19, 'د یوې جګړه‌مارې ښځې سره په غوسه کې اوسېدلو نه په دښته کې ځانته اوسېدل ښه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_19.mp3', '', 1761754199, 1761754199),
(43575, 'Proverbs 21:20', 'Proverbs', 21, 20, 'د هوښیار انسان کور د عطرو او د قیمتي خزانو نه ډک وي خو کم‌عقل چې څه ګټي هغه څټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_20.mp3', '', 1761754199, 1761754199),
(43576, 'Proverbs 21:21', 'Proverbs', 21, 21, 'څوک چې نېکي کوي او په مهربانۍ پسې ګرځي نو اوږد ژوند، نېکمرغي او عزت به تر‌لاسه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_21.mp3', '', 1761754199, 1761754199),
(43577, 'Proverbs 21:22', 'Proverbs', 21, 22, 'یو هوښیار انسان د جنګیالیو د ښار په لویو دېوالونو ختلی شي او هغه کلک دېوالونه یې راغورځولی شي چې هغوی ورباندې ټینګ باور لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_22.mp3', '', 1761754199, 1761754199),
(43578, 'Proverbs 21:23', 'Proverbs', 21, 23, 'څوک چې خوله او ژبه په خپل واک کې ساتي نو خپل ځان د سختۍ او تکلیف نه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_23.mp3', '', 1761754199, 1761754199),
(43579, 'Proverbs 21:24', 'Proverbs', 21, 24, 'کبرجن او مغرور سړی به د ملنډې وهونکي په نوم مشهور شي چې چلند به یې تل د غرور او غوسې نه ډک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_24.mp3', '', 1761754199, 1761754199),
(43580, 'Proverbs 21:25', 'Proverbs', 21, 25, 'د لټ انسان لوږه هغه د مرګ په لور بیایي ځکه چې د کار کولو نه انکار کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_25.mp3', '', 1761754199, 1761754199),
(43581, 'Proverbs 21:26', 'Proverbs', 21, 26, 'د هغه ټوله ورځ ډېرو شیانو ته سخت زړه کیږي خو نېک سړی سخاوت کوي او د سختۍ نه ځان ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_26.mp3', '', 1761754199, 1761754199),
(43582, 'Proverbs 21:27', 'Proverbs', 21, 27, 'که څښتن ته د بدکارانو قرباني د کرکې وړ وي نو په بدنیتۍ سره قرباني ورکول به څومره نامناسبه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_27.mp3', '', 1761754199, 1761754199),
(43583, 'Proverbs 21:28', 'Proverbs', 21, 28, 'دروغجن شاهد به تباه شي خو څوک چې نورو ته غوږ نیسي خبرې به یې تلپاتې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_28.mp3', '', 1761754199, 1761754199),
(43584, 'Proverbs 21:29', 'Proverbs', 21, 29, 'د بدکاره سړي په مخکې سپین‌سترګي ښکاري خو رښتینی انسان په خپله لار ډاډمن قدمونه پورته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_29.mp3', '', 1761754199, 1761754199),
(43585, 'Proverbs 21:30', 'Proverbs', 21, 30, 'هېڅ داسې حکمت، پوهه او انساني فکر نشته چې د څښتن په خلاف بریالیتوب ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_30.mp3', '', 1761754199, 1761754199),
(43586, 'Proverbs 21:31', 'Proverbs', 21, 31, 'اس د جنګ د ورځې دپاره تیاریږي خو بریالیتوب د څښتن په لاس کې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs21_verse_31.mp3', '', 1761754199, 1761754199),
(43587, 'Jeremiah 40:1', 'Jeremiah', 40, 1, 'د مالِک خُدائ پېغام يرمياه ته پس د هغې نه ورکړے شو کله چې د فوج کمانډر نبوزردان هغه په راما کښې آزاد کړو. نو هغۀ يرمياه هم د يروشلم او يهوداه په هغه کسانو کښې په زنځيرونو تړلے وموندلو څوک چې بابل ته جلاوطن کېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_1.mp3', '', 1761754199, 1761754199),
(43588, 'Jeremiah 40:2', 'Jeremiah', 40, 2, 'د فوج کمانډر يرمياه ته آواز وکړو او ورته يې ووئيل چې، ”مالِک خُدائ ستا مقدس رب دا تباهى په دې مُلک نازله کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_2.mp3', '', 1761754199, 1761754199),
(43589, 'Jeremiah 40:3', 'Jeremiah', 40, 3, 'لکه څنګه چې هغۀ فرمائيلى وُو هغه شان يې وکړل. ځکه چې دې خلقو د مالِک خُدائ خلاف ګناه وکړه او د هغۀ نافرمانى يې وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_3.mp3', '', 1761754199, 1761754199),
(43590, 'Jeremiah 40:4', 'Jeremiah', 40, 4, 'خو زۀ اوس ستا د لاسونو نه زنځيرونه اخوا کوم او تا آزادوم. کۀ تۀ ما سره بابل ته تلل غواړې، نو راځه چې ځُو. زۀ به ګورم چې ستا پوره خيال وساتلے شى. او کۀ تۀ ما سره هلته تلل نۀ غواړې، نو دلته ايسار شه. ټول مُلک ستا د وړاندې دے. چرته چې تۀ تلل غواړې نو هلته په آزاده توګه لاړ شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_4.mp3', '', 1761754199, 1761754199),
(43591, 'Jeremiah 40:5', 'Jeremiah', 40, 5, 'کۀ چرې تا دا فېصله کړې وى چې دلته پاتې شې، نو بيا جدلياه د اخيقام زوئ او د سافن نمسى ته واپس لاړ شه. هغه د بابل بادشاه له طرفه د يهوداه حکمران مقرر شوے دے. د هغه خلقو سره پاتې شه په چا چې هغه حکومت کوى. خو دا ستا خوښه ده، چرته دې چې زړۀ غواړى هلته لاړ شه.“ نو بيا نبوزردان يرمياه ته څۀ خوراک او پېسې ورکړې او هغۀ ته يې ووئيل چې لاړ شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_5.mp3', '', 1761754199, 1761754199),
(43592, 'Jeremiah 40:6', 'Jeremiah', 40, 6, 'نو بيا يرمياه جدلياه د اخيقام زوئ له په مصفاه کښې واپس لاړو، او هغه په يهوداه کښې د هغه خلقو سره اوسېدلو کوم چې په هغه مُلک کښې پاتې شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_6.mp3', '', 1761754199, 1761754199),
(43593, 'Jeremiah 40:7', 'Jeremiah', 40, 7, 'د يهوداه څۀ فوجى آفسران چې په کلى والو علاقو کښې پټ شوى وُو، هغوئ دا واورېدل چې په يهوداه کښې جدلياه د اخيقام زوئ په غريبانانو خلقو باندې د بابل بادشاه حکمران مقرر کړے دے. په هغوئ کښې نارينه، زنانه، او ماشومان شامل دى څوک چې بابل ته جلاوطن کړے شوى نۀ وُو او په يهوداه کښې پاتې وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_7.mp3', '', 1761754199, 1761754199),
(43594, 'Jeremiah 40:8', 'Jeremiah', 40, 8, 'په هغوئ کښې دا آفسران شامل دى، اِسمٰعيل د نتنياه زوئ، يوحانان او يونتن د قريح زامن، شراياه د تنحومت زوئ، د عيفاى نطوفاتى زامن، يزنياه د معکاتى زوئ او د هغوئ فوجيان. هغوئ د جدلياه د ليدو دپاره مصفاه ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_8.mp3', '', 1761754199, 1761754199),
(43595, 'Jeremiah 40:9', 'Jeremiah', 40, 9, 'جدلياه د اخيقام زوئ او د سافن نمسى هغوئ سره په قسم خوړلو وعده وکړه چې، ”د خپل ځان په حواله کېدو بابليانو نه مۀ يرېږئ. د هغوئ د خِدمت کولو نه مۀ يرېږئ. په دې مُلک کښې اوسېږئ، او د بابل د بادشاه خِدمت کوئ او هر څۀ به ستاسو دپاره د خير وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_9.mp3', '', 1761754199, 1761754199),
(43596, 'Jeremiah 40:10', 'Jeremiah', 40, 10, 'زۀ به په خپله په مصفاه کښې اوسېږم او کله چې د بابليانو وفد دلته راشى نو زۀ به ستاسو د طرف نه نمائنده يم. خو په دې وخت کښې تاسو انګور، او د ګرمۍ مېوې، او د زيتُونو تېل په چاټو کښې جمع کړئ، او په کومو ښارونو مو چې قبضه کړې ده په هغوئ کښې اوسېږئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_10.mp3', '', 1761754199, 1761754199),
(43597, 'Jeremiah 40:11', 'Jeremiah', 40, 11, 'په دې دوران کښې چې کوم د يهوديانو خلق چې موآب، عمون، ادوم او نورو مُلکونو ته مسافر شوى وُو نو هغوئ ټول په دې خبر شول چې د بابل بادشاه د يهوداه پاتې شوى خلقو له په يهوداه کښې د اوسېدو اجازت ورکړے دے او جدلياه يې د هغوئ حکمران جوړ کړے دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_11.mp3', '', 1761754199, 1761754199),
(43598, 'Jeremiah 40:12', 'Jeremiah', 40, 12, 'نو بيا هغوئ ټول د يهوداه مُلک ته واپس راغلل، په مصفاه کښې جدلياه ته، د هغه ټولو مُلکونو نه کوم ته چې هغوئ خوارۀ شوى وُو. او هغوئ د اوړى ډيرې مېوې او انګور راټول کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_12.mp3', '', 1761754199, 1761754199),
(43599, 'Jeremiah 40:13', 'Jeremiah', 40, 13, 'د هغې نه پس، د قريح زوئ يوحانان او هغه فوجى آفسران څوک چې په کلى والو علاقو کښې وُو، په مصفاه کښې جدلياه له راغلل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_13.mp3', '', 1761754199, 1761754199),
(43600, 'Jeremiah 40:14', 'Jeremiah', 40, 14, 'هغوئ هغۀ ته ووئيل چې، ”تا ته دا پته شته چې بعليس د عمون بادشاه اِسمٰعيل د نتنياه زوئ ستا د قتلولو دپاره رالېږلے دے؟“ خو جدلياه په دې خبره باندې يقين ونۀ کړلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_14.mp3', '', 1761754199, 1761754199),
(43601, 'Jeremiah 40:15', 'Jeremiah', 40, 15, 'نو د قريح زوئ يوحانان هغۀ ته پټ غوندې ووئيل، ”ما پرېږده چې د نتنياه زوئ اِسمٰعيل ووژنم او هيچا ته به د دې پته ونۀ لګى. ولې مونږ هغۀ ته اجازت ورکړُو چې هغه راشى او تا ووژنى؟ د يهوداه د هغه خلقو به څۀ حال وى څوک چې واپس خپل مُلک ته راغلل او ستا په مشرۍ کښې راټول شول؟ نو بيا ولې دې مونږ د يهوداه دا لږ کسان کوم چې ژوندى يُو خوارۀ وارۀ او ورک شُو؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_15.mp3', '', 1761754199, 1761754199),
(43602, 'Jeremiah 40:16', 'Jeremiah', 40, 16, 'خو جدلياه يوحانان ته په جواب کښې ووئيل، ”زۀ تا په سختۍ سره منع کوم دا کار مۀ کوه. تۀ چې د اِسمٰعيل په حقله څۀ وائې نو هغه رښتيا نۀ دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah40_verse_16.mp3', '', 1761754199, 1761754199),
(43603, 'Proverbs 16:1', 'Proverbs', 16, 1, 'انسان په خپل زړه کې ډېرې نقشې جوړوي خو وروستنۍ خبره د څښتن په لاس کې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_1.mp3', '', 1761754199, 1761754199),
(43604, 'Proverbs 16:2', 'Proverbs', 16, 2, 'د انسان په نظر خپلې ټولې لارې پاکې ښکاري خو څښتن د زړونو په رازونو قضاوت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_2.mp3', '', 1761754199, 1761754199),
(43605, 'Proverbs 16:3', 'Proverbs', 16, 3, 'خپل ټول کارونه څښتن ته وسپاره نو ستا نقشې به بریالې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_3.mp3', '', 1761754199, 1761754199),
(43606, 'Proverbs 16:4', 'Proverbs', 16, 4, 'څښتن هرڅه د خپل مقصد دپاره پیدا کړي دي او حتی بدکاران یې د تباهۍ د ورځې دپاره پیدا کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_4.mp3', '', 1761754199, 1761754199),
(43607, 'Proverbs 16:5', 'Proverbs', 16, 5, 'څښتن له ټولو کبرجنو خلکو نه کرکه کوي او باور ولره چې بې‌سزا به پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_5.mp3', '', 1761754199, 1761754199),
(43608, 'Proverbs 16:6', 'Proverbs', 16, 6, 'د مینې او وفادارۍ له امله ګناه بخښل کیږي د څښتن له وېرې انسان له بدۍ او بلاګانو ساتل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_6.mp3', '', 1761754199, 1761754199),
(43609, 'Proverbs 16:7', 'Proverbs', 16, 7, 'کله چې څښتن د انسان له کړو نه راضي وي نو دښمنان یې هم له هغه سره په امن کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_7.mp3', '', 1761754199, 1761754199),
(43610, 'Proverbs 16:8', 'Proverbs', 16, 8, 'په صداقت سره لږه ګټه ښه وي له هغې ډېرې ګټې نه چې په بې‌انصافۍ سره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_8.mp3', '', 1761754199, 1761754199);